/// Lines that are empty/blank or that start with `#` (comments) are skipped. The
/// remaining patterns are returned in their original order.
fn read_prettier_ignore_file(
    fs: &DynRef<'_, dyn FileSystem>,
) -> Result<Option<Vec<String>>, CliDiagnostic> {
    let open_options = OpenOptions::default().read(true);
    let path = Path::new(PRETTIER_IGNORE_FILE);
