            if let Err(err) = file.read_to_string(&mut content) {
                return Err(CliDiagnostic::io_error(err));
            }
            let patterns = content
                .lines()
                .map(|line| line.trim())
                .filter(|line| !line.is_empty() && !line.starts_with('#'))
                .map(String::from)
                .collect();
            Ok(Some(patterns))
        }
        Err(_) => Ok(None),
    }
}

